/**
 * SVG 导出（P0-6，零依赖矢量交付）+ 导出前的令牌内联。
 *
 * 为什么自研（SPEC §B.1 P0-6 / OSS §12 缺口 4）：2D 图层的 SVG DOM 已经在手，
 * 「克隆 + 内联令牌字面值 + 序列化」即得矢量图；引 `html-to-image` / `modern-screenshot`
 * 反而引入跨浏览器字体与外链坑（SPEC §H.4 明确不装）。
 *
 * 强制契约（SPEC §F.6）：
 * - **R-EXP-1**：SVG 呈现属性必须是**字面值**，⛔ 不能是 `var(--ds-*)`。本模块对克隆体做一次
 *   "CSS 变量 → 字面值"的替换作为**兜底**（正常路径下 2D 图层本来就写的是 `theme.resolve()`）。
 * - **R-EXP-2**：字体族内联，保证导出后字形一致。
 * - **R-EXP-3**（PNG 共用）：`viewBox = plan.bounds`、默认宽 3200px、清空选中层、
 *   背景矩形用 `theme.resolve('canvas')` 的字面值（替换原硬编码，L1886-1888）。
 * - **R-EXP-5**：文件头写 `<!-- generated by decoration-studio; units: mm -->`。
 *
 * ⛔ 本文件不得出现十六进制色值（SPEC §C.2 B3）：颜色一律由调用方经 `resolve()` 传入。
 */
import { CSS_VAR_PREFIX } from '@/theme/applyTheme';
import { THEME_TOKEN_NAMES } from '@/theme/tokens';
import { stampedName } from './download';
import type { Bounds } from '@/types/geometry';
import type { ThemeTokenName } from '@/types/theme';

/** 文件头（R-EXP-5） */
export const SVG_HEADER_COMMENT = '<!-- generated by decoration-studio; units: mm -->';

export const SVG_NS = 'http://www.w3.org/2000/svg';

/** 导出宽度（原 `exportPNG()` 的 3200px，OF §7.1 L1886） */
export const DEFAULT_EXPORT_WIDTH = 3200;

/** 导出字体（R-EXP-2；与原 `<svg>` 上的 font-family 同族） */
export const PLAN_FONT_FAMILY = "'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif";

/** 默认要清掉的图层：选中层（原实现清空 `#gSel`，OF §7.1） */
export const DEFAULT_REMOVE_SELECTORS: readonly string[] = ['#gSel', '[data-layer="SelectionLayer"]'];

/**
 * `var(--ds-<token>)` 匹配（含 fallback 写法）。
 * 用字符串拼出来而不是写字面量：SPEC §C.2 B9 的源码扫描会拦住任何 `fill="var(--ds-…)"` 形态，
 * 这里连"长得像"都不留。
 */
const VAR_PATTERN = new RegExp(`var\\(\\s*${CSS_VAR_PREFIX}([a-zA-Z0-9-]+)[^)]*\\)`, 'g');

export interface SvgExportOptions {
  /** 户型包围盒（`plan.bounds`） */
  bounds: Bounds;
  /** 取字面值：`theme.resolve()`（⛔ 不要传 `readStyle()` 之类的运行时读值） */
  resolve: (name: ThemeTokenName) => string;
  /** 导出像素宽（默认 3200） */
  width?: number;
  /** 背景色字面值：传 `resolve('canvas')`；`false` = 不加背景 */
  background?: string | false;
  /** 需要清掉的节点选择器（默认清选中层） */
  removeSelectors?: readonly string[];
  /** 字体内联（R-EXP-2） */
  fontFamily?: string;
}

export interface PreparedSvg {
  node: SVGSVGElement;
  width: number;
  height: number;
  /** 被内联的 CSS 变量个数（0 = 图层本来就写的是字面值，正常路径） */
  inlinedVars: number;
}

function resolveTokenLiteral(name: string, resolve: (n: ThemeTokenName) => string): string | null {
  if (!(THEME_TOKEN_NAMES as readonly string[]).includes(name)) return null;
  const literal = resolve(name as ThemeTokenName);
  return literal && literal.trim() ? literal : null;
}

/** 把克隆体里所有 `var(--ds-*)` 形态的**属性值**替换成字面值（R-EXP-1 兜底） */
export function inlineTokenVars(root: Element, resolve: (name: ThemeTokenName) => string): number {
  let count = 0;
  const walk = (element: Element): void => {
    for (const attribute of Array.from(element.attributes)) {
      if (!attribute.value.includes('var(')) continue;
      const replaced = attribute.value.replace(VAR_PATTERN, (match: string, name: string) => {
        const literal = resolveTokenLiteral(name, resolve);
        if (!literal) return match;
        count += 1;
        return literal;
      });
      if (replaced !== attribute.value) element.setAttribute(attribute.name, replaced);
    }
    for (const child of Array.from(element.children)) walk(child);
  };
  walk(root);
  return count;
}

/**
 * 克隆 2D 的 `<svg>` 并做导出前处理（R-EXP-1/2/3/5）。
 * ⛔ 不修改原节点（导出后画面不受影响）。
 */
export function prepareSvgCopy(source: SVGSVGElement, options: SvgExportOptions): PreparedSvg {
  const bounds = options.bounds;
  const width = Math.max(1, Math.round(options.width ?? DEFAULT_EXPORT_WIDTH));
  const ratio = bounds.w > 0 ? bounds.h / bounds.w : 0.75;
  const height = Math.max(1, Math.round(width * (ratio > 0 ? ratio : 0.75)));

  const clone = source.cloneNode(true) as SVGSVGElement;
  clone.setAttribute('xmlns', SVG_NS);
  clone.setAttribute('xmlns:xlink', 'http://www.w3.org/1999/xlink');
  if (bounds.w > 0 && bounds.h > 0) {
    clone.setAttribute('viewBox', `${bounds.x} ${bounds.y} ${bounds.w} ${bounds.h}`);
  }
  clone.setAttribute('width', String(width));
  clone.setAttribute('height', String(height));
  if (!clone.getAttribute('font-family')) {
    clone.setAttribute('font-family', options.fontFamily ?? PLAN_FONT_FAMILY);
  }

  for (const selector of options.removeSelectors ?? DEFAULT_REMOVE_SELECTORS) {
    clone.querySelectorAll(selector).forEach((node) => node.remove());
  }

  if (options.background && bounds.w > 0 && bounds.h > 0) {
    const doc = clone.ownerDocument;
    const rect = doc.createElementNS(SVG_NS, 'rect');
    rect.setAttribute('x', String(bounds.x));
    rect.setAttribute('y', String(bounds.y));
    rect.setAttribute('width', String(bounds.w));
    rect.setAttribute('height', String(bounds.h));
    // 字面值（调用方传 `resolve('canvas')`）：SVG 呈现属性不支持 var()（R-EXP-1）
    rect.setAttribute('fill', options.background);
    clone.insertBefore(rect, clone.firstChild);
  }

  const inlinedVars = inlineTokenVars(clone, options.resolve);
  return { node: clone, width, height, inlinedVars };
}

export interface SvgDocument {
  text: string;
  width: number;
  height: number;
  inlinedVars: number;
}

/** 完整 SVG 文档文本（带 R-EXP-5 文件头） */
export function serializeSvgDocument(source: SVGSVGElement, options: SvgExportOptions): SvgDocument {
  const prepared = prepareSvgCopy(source, options);
  const body = new XMLSerializer().serializeToString(prepared.node);
  return {
    text: `${SVG_HEADER_COMMENT}\n${body}\n`,
    width: prepared.width,
    height: prepared.height,
    inlinedVars: prepared.inlinedVars,
  };
}

export interface PngResult {
  ok: true;
  blob: Blob;
  width: number;
  height: number;
  inlinedVars: number;
}
export interface ExportFailure {
  ok: false;
  reason: string;
}
export type ExportResult = PngResult | ExportFailure;

function loadImage(url: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error('svg-image-decode-failed'));
    image.src = url;
  });
}

function canvasToBlob(canvas: HTMLCanvasElement): Promise<Blob> {
  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => {
      if (blob) resolve(blob);
      else reject(new Error('canvas-toBlob-null'));
    }, 'image/png');
  });
}

/**
 * 2D 平面 → PNG（R-EXP-3 的完整流程：克隆 → viewBox → 3200px → 清选中层 → 背景矩形 →
 * `Image` → `canvas` → `toBlob`）。失败返回结构化原因，⛔ 不伪造产物。
 */
export async function buildPlanPng(source: SVGSVGElement, options: SvgExportOptions): Promise<ExportResult> {
  if (typeof document === 'undefined' || typeof Image === 'undefined') return { ok: false, reason: 'no-dom' };
  let url = '';
  try {
    const prepared = prepareSvgCopy(source, options);
    const svgText = new XMLSerializer().serializeToString(prepared.node);
    const svgBlob = new Blob([svgText], { type: 'image/svg+xml;charset=utf-8' });
    url = URL.createObjectURL(svgBlob);
    const image = await loadImage(url);
    const canvas = document.createElement('canvas');
    canvas.width = prepared.width;
    canvas.height = prepared.height;
    const ctx = canvas.getContext('2d');
    if (!ctx) return { ok: false, reason: 'no-2d-context' };
    ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
    const blob = await canvasToBlob(canvas);
    return { ok: true, blob, width: canvas.width, height: canvas.height, inlinedVars: prepared.inlinedVars };
  } catch (error) {
    return { ok: false, reason: error instanceof Error ? error.message : String(error) };
  } finally {
    if (url) URL.revokeObjectURL(url);
  }
}

export function svgFileName(base: string, at?: Date): string {
  return stampedName(base, 'svg', at);
}

export function pngFileName(base: string, at?: Date): string {
  return stampedName(base, 'png', at);
}